import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { randomUUID } from 'node:crypto';

/**
 * Tiny JSON-file-backed store for books.
 * No database, no accounts. Books survive restarts because they live in a
 * plain JSON file on disk.
 */
export class BookStore {
  /**
   * @param {string} filePath - Absolute path to the JSON file.
   */
  constructor(filePath) {
    this.filePath = filePath;
    /** @type {import('./types.js').Book[]} */
    this.books = [];
  }

  /** Load books from disk, creating the file if missing. */
  async load() {
    if (!existsSync(this.filePath)) {
      this.books = [];
      await this.persist();
      return;
    }
    try {
      const raw = await readFile(this.filePath, 'utf8');
      const parsed = JSON.parse(raw);
      this.books = Array.isArray(parsed) ? parsed : [];
    } catch {
      // Corrupt or empty file — start fresh rather than crashing.
      this.books = [];
    }
  }

  /** Persist the current books array to disk atomically-ish. */
  async persist() {
    await mkdir(dirname(this.filePath), { recursive: true });
    await writeFile(this.filePath, JSON.stringify(this.books, null, 2), 'utf8');
  }

  /** @returns {import('./types.js').Book[]} */
  all() {
    return [...this.books];
  }

  /** @returns {import('./types.js').Book[]} */
  currentlyReading() {
    return this.books.filter((b) => !b.finished);
  }

  /** @returns {import('./types.js').Book[]} */
  finished() {
    return this.books.filter((b) => b.finished);
  }

  /**
   * @param {{title:string; author:string; notes?:string; finished?:boolean}} input
   * @returns {import('./types.js').Book}
   */
  async add(input) {
    const book = {
      id: randomUUID(),
      title: input.title.trim(),
      author: input.author.trim(),
      notes: (input.notes ?? '').trim(),
      finished: Boolean(input.finished),
      createdAt: new Date().toISOString(),
    };
    this.books.push(book);
    await this.persist();
    return book;
  }

  /**
   * @param {string} id
   * @returns {import('./types.js').Book | null}
   */
  get(id) {
    return this.books.find((b) => b.id === id) ?? null;
  }

  /**
   * @param {string} id
   * @returns {import('./types.js').Book | null} the updated book, or null if not found
   */
  async markFinished(id) {
    const book = this.get(id);
    if (!book) return null;
    book.finished = true;
    await this.persist();
    return book;
  }

  /**
   * @param {string} id
   * @returns {boolean} true if a book was removed
   */
  async remove(id) {
    const before = this.books.length;
    this.books = this.books.filter((b) => b.id !== id);
    const removed = this.books.length < before;
    if (removed) await this.persist();
    return removed;
  }
}

/** Default store path, overridable via env for tests. */
export function defaultStorePath() {
  const dataDir = process.env.BOOKS_DATA_DIR ?? join(process.cwd(), 'data');
  return join(dataDir, 'books.json');
}

