/**
 * Minimal HTML escape for user-provided strings rendered into the page.
 * @param {string} str
 * @returns {string}
 */
export function esc(str) {
  return String(str ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

/** @param {string} str */
export function nl2br(str) {
  return esc(str).replaceAll('\n', '<br>');
}

