import { esc, nl2br } from './escape.js';

/**
 * @param {string} title
 * @param {string} body
 * @returns {string}
 */
export function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${esc(title)}</title>
  <style>
    :root {
      --bg: #faf8f4;
      --card: #ffffff;
      --ink: #2a2a2a;
      --muted: #7a7468;
      --line: #e6e0d4;
      --accent: #6b4f3b;
      --accent-ink: #fff;
      --done: #4a7c4e;
      --shadow: 0 1px 3px rgba(0,0,0,.06), 0 1px 2px rgba(0,0,0,.04);
    }
    * { box-sizing: border-box; }
    body {
      font: 16px/1.55 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background: var(--bg);
      color: var(--ink);
      margin: 0;
      padding: 2rem 1rem 4rem;
    }
    .wrap { max-width: 640px; margin: 0 auto; }
    header { margin-bottom: 1.5rem; }
    h1 { font-size: 1.6rem; margin: 0 0 .25rem; letter-spacing: -.01em; }
    header p { margin: 0; color: var(--muted); font-size: .95rem; }
    section { margin-bottom: 2rem; }
    h2 { font-size: 1.1rem; margin: 0 0 .75rem; color: var(--accent); font-weight: 600; }
    .card {
      background: var(--card);
      border: 1px solid var(--line);
      border-radius: 10px;
      box-shadow: var(--shadow);
      padding: 1rem 1.1rem;
      margin-bottom: .6rem;
      display: flex;
      align-items: center;
      gap: .8rem;
    }
    .card .meta { flex: 1; min-width: 0; }
    .card .title { font-weight: 600; }
    .card .author { color: var(--muted); font-size: .9rem; }
    .card a { color: var(--ink); text-decoration: none; }
    .card a:hover .title { text-decoration: underline; }
    .badge {
      font-size: .72rem; font-weight: 600; letter-spacing: .04em;
      text-transform: uppercase; padding: .15rem .5rem; border-radius: 999px;
      background: #efe9dd; color: var(--accent); white-space: nowrap;
    }
    .badge.done { background: #e3efe4; color: var(--done); }
    .empty { color: var(--muted); font-style: italic; padding: .25rem 0; }
    form { background: var(--card); border: 1px solid var(--line); border-radius: 10px; box-shadow: var(--shadow); padding: 1.1rem; }
    label { display: block; font-size: .85rem; font-weight: 600; margin: .6rem 0 .25rem; color: var(--muted); }
    input[type=text], textarea {
      width: 100%; font: inherit; padding: .5rem .6rem; border: 1px solid var(--line);
      border-radius: 7px; background: #fff; color: var(--ink);
    }
    textarea { min-height: 80px; resize: vertical; }
    input[type=text]:focus, textarea:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 2px rgba(107,79,59,.12); }
    .row { display: flex; gap: .6rem; align-items: center; flex-wrap: wrap; }
    .check { display: inline-flex; align-items: center; gap: .35rem; font-size: .9rem; color: var(--muted); }
    button, .btn {
      font: inherit; font-weight: 600; cursor: pointer; border: none; border-radius: 7px;
      padding: .5rem .9rem; background: var(--accent); color: var(--accent-ink);
    }
    .btn.ghost { background: transparent; color: var(--muted); border: 1px solid var(--line); }
    .btn.ghost:hover { color: var(--ink); }
    .btn.small { padding: .3rem .6rem; font-size: .85rem; }
    .actions { display: flex; gap: .5rem; flex-wrap: wrap; margin-top: 1rem; }
    .notes { white-space: normal; margin-top: 1rem; line-height: 1.6; }
    .back { display: inline-block; margin-bottom: 1rem; font-size: .9rem; }
    .flash { background: #e3efe4; color: var(--done); border-radius: 7px; padding: .5rem .8rem; margin-bottom: 1rem; font-size: .9rem; }
    .share { display: flex; gap: .5rem; align-items: center; margin-top: 1rem; }
    .share input { flex: 1; font-family: ui-monospace, monospace; font-size: .85rem; }
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <h1><a href="/" style="color:inherit;text-decoration:none">Reading List</a></h1>
      <p>What you're reading and what you've finished.</p>
    </header>
    ${body}
  </div>
</body>
</html>`;
}

/** @param {import('./types.js').Book[]} books */
function bookCard(books) {
  return books
    .map(
      (b) => `      <div class="card">
        <span class="badge ${b.finished ? 'done' : ''}">${b.finished ? 'Finished' : 'Reading'}</span>
        <div class="meta">
          <a href="/books/${esc(b.id)}"><div class="title">${esc(b.title)}</div></a>
          <div class="author">${esc(b.author)}</div>
        </div>
        ${
          b.finished
            ? ''
            : `<form method="post" action="/books/${esc(b.id)}/finish" style="margin:0"><button class="btn small" type="submit">Mark finished</button></form>`
        }
      </div>`
    )
    .join('\n') || '      <p class="empty">Nothing here yet.</p>';
}

/**
 * @param {{reading: import('./types.js').Book[], finished: import('./types.js').Book[], flash?: string}} props
 */
export function homePage({ reading, finished, flash }) {
  return page('Reading List', `
    ${flash ? `    <div class="flash">${esc(flash)}</div>` : ''}
    <section>
      <h2>Currently reading</h2>
${bookCard(reading)}
    </section>
    <section>
      <h2>Finished</h2>
${bookCard(finished)}
    </section>
    <section>
      <h2>Add a book</h2>
      <form method="post" action="/books">
        <label for="title">Title</label>
        <input id="title" name="title" type="text" required autocomplete="off">
        <label for="author">Author</label>
        <input id="author" name="author" type="text" required autocomplete="off">
        <label for="notes">Notes</label>
        <textarea id="notes" name="notes"></textarea>
        <div class="row" style="margin-top:.8rem">
          <label class="check"><input type="checkbox" name="finished"> Already finished</label>
          <span style="flex:1"></span>
          <button type="submit">Add book</button>
        </div>
      </form>
    </section>`);
}

/**
 * @param {{book: import('./types.js').Book}, baseUrl: string}} props
 */
export function bookPage({ book, baseUrl }) {
  const shareUrl = `${baseUrl}/books/${esc(book.id)}`;
  return page(book.title, `
    <a class="back" href="/">&larr; Back to list</a>
    <div class="card" style="display:block">
      <div class="row" style="justify-content:space-between">
        <span class="badge ${book.finished ? 'done' : ''}">${book.finished ? 'Finished' : 'Reading'}</span>
      </div>
      <h2 style="margin:.6rem 0 .2rem">${esc(book.title)}</h2>
      <div class="author">${esc(book.author)}</div>
      <div class="actions">
        ${
          book.finished
            ? ''
            : `<form method="post" action="/books/${esc(book.id)}/finish" style="margin:0"><button type="submit">Mark finished</button></form>`
        }
        <form method="post" action="/books/${esc(book.id)}/delete" style="margin:0" onsubmit="return confirm('Delete this book?')">
          <button type="submit" class="btn ghost">Delete</button>
        </form>
      </div>
      <div class="share">
        <input type="text" id="shareurl" value="${shareUrl}" readonly onclick="this.select()">
        <button type="button" class="btn small" onclick="navigator.clipboard.writeText('${shareUrl}'); this.textContent='Copied'">Copy link</button>
      </div>
      <h3 style="margin:1.2rem 0 .3rem;font-size:.95rem;color:var(--muted)">Notes</h3>
      <div class="notes">${book.notes ? nl2br(book.notes) : '<span class="empty">No notes yet.</span>'}</div>
    </div>`);
}

export function notFoundPage() {
  return page('Not found', `
    <a class="back" href="/">&larr; Back to list</a>
    <div class="card" style="display:block"><p>That book could not be found.</p></div>`);
}

