import { createServer } from 'node:http';
import { BookStore, defaultStorePath } from './store.js';
import { homePage, bookPage, notFoundPage } from './views.js';

const PORT = Number(process.env.PORT ?? 3000);
const store = new BookStore(defaultStorePath());

/** @param {import('node:http').IncomingMessage} req */
function baseUrl(req) {
  const proto = req.headers['x-forwarded-proto'] || 'http';
  const host = req.headers.host || `localhost:${PORT}`;
  return `${proto}://${host}`;
}

/** Parse a urlencoded form body into a plain object. */
async function parseForm(req) {
  const chunks = [];
  for await (const c of req) chunks.push(c);
  const raw = Buffer.concat(chunks).toString('utf8');
  const out = {};
  for (const pair of raw.split('&')) {
    if (!pair) continue;
    const [k, ...rest] = pair.split('=');
    const key = decodeURIComponent(k.replace(/\+/g, ' '));
    const val = decodeURIComponent(rest.join('=').replace(/\+/g, ' '));
    out[key] = val;
  }
  return out;
}

/** @param {import('node:http').ServerResponse} res */
function send(res, status, body, headers = {}) {
  res.writeHead(status, { 'content-type': 'text/html; charset=utf-8', ...headers });
  res.end(body);
}

/** @param {import('node:http').ServerResponse} res */
function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

/** @param {import('node:http').IncomingMessage} req @param {import('node:http').ServerResponse} res */
async function handler(req, res) {
  const url = new URL(req.url, 'http://localhost');

  // Home: list currently reading + finished, plus add form.
  if (url.pathname === '/' && req.method === 'GET') {
    return send(
      res,
      200,
      homePage({
        reading: store.currentlyReading(),
        finished: store.finished(),
        flash: url.searchParams.get('flash') || undefined,
      })
    );
  }

  // Create a book.
  if (url.pathname === '/books' && req.method === 'POST') {
    const form = await parseForm(req);
    if (!form.title || !form.author) {
      return send(res, 400, page400('Title and author are required.'));
    }
    const book = await store.add({
      title: form.title,
      author: form.author,
      notes: form.notes,
      finished: form.finished === 'on',
    });
    return redirect(res, `/books/${book.id}?flash=added`);
  }

  // Show a single book (shareable link).
  const showMatch = url.pathname.match(/^\/books\/([^/]+)$/);
  if (showMatch && req.method === 'GET') {
    const book = store.get(showMatch[1]);
    if (!book) return send(res, 404, notFoundPage());
    return send(res, 200, bookPage({ book, baseUrl: baseUrl(req) }));
  }

  // Mark a book finished.
  const finishMatch = url.pathname.match(/^\/books\/([^/]+)\/finish$/);
  if (finishMatch && req.method === 'POST') {
    const book = await store.markFinished(finishMatch[1]);
    if (!book) return send(res, 404, notFoundPage());
    return redirect(res, `/books/${book.id}?flash=finished`);
  }

  // Delete a book.
  const deleteMatch = url.pathname.match(/^\/books\/([^/]+)\/delete$/);
  if (deleteMatch && req.method === 'POST') {
    await store.remove(deleteMatch[1]);
    return redirect(res, '/?flash=deleted');
  }

  return send(res, 404, notFoundPage());
}

function page400(message) {
  return `<!doctype html><html><head><meta charset="utf-8"><title>Error</title></head>
  <body><p>${message}</p><p><a href="/">Back</a></p></body></html>`;
}

async function main() {
  await store.load();
  const server = createServer((req, res) => {
    handler(req, res).catch((err) => {
      console.error(err);
      if (!res.headersSent) send(res, 500, page400('Something went wrong.'));
    });
  });
  server.listen(PORT, () => {
    console.log(`Reading list app running: http://localhost:${PORT}`);
  });
}

const isMain = process.argv[1] && import.meta.url === `file://${process.argv[1]}`;
if (isMain) main();

