import { describe, it, expect, beforeEach } from 'vitest';
import { BookStore } from '../store.js';
import { mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

function makeStore() {
  const dir = mkdtempSync(join(tmpdir(), 'books-'));
  const store = new BookStore(join(dir, 'books.json'));
  return { store, dir };
}

describe('BookStore', () => {
  let store, dir;

  beforeEach(async () => {
    ({ store, dir } = makeStore());
    await store.load();
  });

  afterEach?.(() => {
    try { rmSync(dir, { recursive: true, force: true }); } catch {}
  });

  it('starts empty and persists an empty file', () => {
    expect(store.all()).toEqual([]);
  });

  it('adds a book and reads it back', async () => {
    const b = await store.add({ title: 'The Pragmatic Programmer', author: 'Hunt & Thomas' });
    expect(b.id).toBeTruthy();
    expect(b.finished).toBe(false);
    expect(store.all()).toHaveLength(1);
    expect(store.get(b.id).title).toBe('The Pragmatic Programmer');
  });

  it('separates currently reading from finished', async () => {
    await store.add({ title: 'A', author: 'x' });
    await store.add({ title: 'B', author: 'y', finished: true });
    expect(store.currentlyReading().map((b) => b.title)).toEqual(['A']);
    expect(store.finished().map((b) => b.title)).toEqual(['B']);
  });

  it('marks a book finished', async () => {
    const b = await store.add({ title: 'C', author: 'z' });
    await store.markFinished(b.id);
    expect(store.get(b.id).finished).toBe(true);
    expect(store.finished()).toHaveLength(1);
    expect(store.currentlyReading()).toHaveLength(0);
  });

  it('removes a book', async () => {
    const b = await store.add({ title: 'D', author: 'w' });
    const removed = await store.remove(b.id);
    expect(removed).toBe(true);
    expect(store.all()).toHaveLength(0);
  });

  it('survives a restart by reloading from the JSON file', async () => {
    await store.add({ title: 'Persisted', author: 'p', notes: 'hi', finished: true });
    const reloaded = new BookStore(store.filePath);
    await reloaded.load();
    expect(reloaded.all()).toHaveLength(1);
    expect(reloaded.all()[0].title).toBe('Persisted');
    expect(reloaded.all()[0].notes).toBe('hi');
    expect(reloaded.finished()).toHaveLength(1);
  });

  it('returns null for unknown ids', () => {
    expect(store.get('nope')).toBeNull();
    expect(store.markFinished('nope')).resolves.toBeNull();
  });

  it('trims input fields', async () => {
    const b = await store.add({ title: '  Spaced  ', author: '  A  ', notes: '  n  ' });
    expect(b.title).toBe('Spaced');
    expect(b.author).toBe('A');
    expect(b.notes).toBe('n');
  });
});

